ertura'] ?? '') ?></p><?php if (!empty($g['condiciones'])): ?><p class="text-[11px] text-amber-700 mt-2"><i class="fas fa-triangle-exclamation mr-1"></i><?= htmlspecialchars($g['condiciones']) ?></p><?php endif; ?></div><?php endforeach; ?></div><?php if ($vigente): ?><form method="POST" class="space-y-4"><?= emxCsrfCampo() ?><input type="hidden" name="detalle_id" value="<?= htmlspecialchars($detalleId) ?>"><div><label class="block text-sm font-semibold mb-1">Componente afectado</label><select name="componente_afectado" class="w-full border rounded-xl px-3 py-2"><?php foreach ($garantias as $g): ?><option value="<?= htmlspecialchars($g['componente'] ?? 'Garantía general') ?>"><?= htmlspecialchars($g['componente'] ?? 'Garantía general') ?></option><?php endforeach; ?></select></div><div><label class="block text-sm font-semibold mb-1">Número de serie</label><input type="text" name="numero_serie" class="w-full border rounded-xl px-3 py-2" placeholder="Serie del producto si la tienes"></div><div><label class="block text-sm font-semibold mb-1">Describe la falla</label><textarea name="descripcion_falla" required rows="5" class="w-full border rounded-xl px-3 py-2" placeholder="Ej: el motor no enciende, el panel no responde, hace ruido..."></textarea></div><button class="px-5 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700"><i class="fas fa-paper-plane mr-1"></i>Enviar caso de garantía</button></form><?php else: ?><p class="text-sm text-slate-600">Este producto ya no tiene garantía vigente según la fecha de compra y las condiciones registradas.</p><?php endif; ?></div></main><?php if (is_file(EMX_VIEWS_PATH . '/components/footer.php')) include 'components/footer.php'; ?><script src="assets/emx_modales.js"></script></body></html>